"""Build the photo lookbook and permanent attribution records from verified sources."""
from pathlib import Path
import json,html,urllib.parse
R=Path(__file__).resolve().parent.parent
rows=json.loads((R/'assets/ocean-rain-sources.json').read_text())
e=lambda x:html.escape(str(x),quote=True)
slug=lambda x:x.lower().replace(' ','-')
head='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ocean Photography &amp; Rain After Dark | Keepsake</title><meta name="description" content="Real ocean and rainy-night photographs, printed on clear phone cases. Choose your photo, personalize your case, and purchase in store."><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/homepage.css"><link rel="stylesheet" href="assets/shop-menu.css?v=start-case-1"><link rel="stylesheet" href="assets/case-zoom.css"><link rel="stylesheet" href="assets/new-prints.css"><script src="assets/shop-menu.js?v=rated-all-1" defer></script></head><body><a class="skip-link" href="#main">Skip to content</a><div class="announcement"><span>PERSONALIZED IN STORE · CLEAR CASE DESIGNS $44.99</span><a href="index.html#stores">Find your counter ↗</a></div><header class="home-header"><a class="wordmark" href="index.html" aria-label="Keepsake home"><img src="assets/favicon.svg" width="40" height="40" alt=""><span>KEEPSAKE<small>PRINTING CO.</small></span></a><nav class="desktop-nav" aria-label="Main navigation"><a href="gallery.html">Phone cases</a><a href="slates.html">Photo slates</a><a href="index.html#stores">Visit us</a></nav><a class="header-cta" href="customizer.html">Design your case</a></header><main id="main" class="fresh-page"><header class="fresh-intro"><p class="eyebrow">REAL PHOTOGRAPHY. YOUR EVERYDAY ESCAPE.</p><h1>Drift away.<br>Stay out late.</h1><p>Ocean blues, rain on glass and streets glowing after dark. Find a photograph that feels like you.</p><p class="fresh-note">Digital previews on clear cases, shown on iPhone 15 Pro.<br>Tap to see the detail. Choose your phone before customizing.</p></header><nav class="fresh-nav" aria-label="Photo collections"><a href="#ocean-photography">Ocean Photography</a><a href="#rain-after-dark">Rain After Dark</a></nav>'''
copy={'Ocean Photography':('Follow the tide.','Sea turtles, underwater forests and the line where the waves meet the shore.'),'Rain After Dark':('A little lost in the lights.','Window drops, glowing reflections and wet streets after dark.')}
page=head
for category,(title,desc) in copy.items():
 page+='<section class="fresh-section" id="'+slug(category)+'"><div class="fresh-heading"><div><p class="eyebrow">'+e(category)+'</p><h2>'+title+'</h2><p>'+desc+'</p></div><a class="fresh-browse" href="gallery.html?cat='+urllib.parse.quote(category)+'">Browse all six photographs →</a></div><div class="fresh-grid">'
 for r in [r for r in rows if r['category']==category]:
  stem=Path(r['file']).stem;href='gallery.html?'+urllib.parse.urlencode({'cat':category,'pick':r['file'],'colorway':'original','back':'ocean-and-rain.html#'+slug(category)})
  page+='<article class="fresh-card"><a data-preview-link data-preview-action="Choose your phone" class="fresh-image" href="'+e(href)+'" aria-label="View '+e(r['title'])+'"><img loading="lazy" decoding="async" width="600" height="1200" src="assets/ocean-rain/'+stem+'.webp" alt="'+e(r['title'])+' photograph printed across the back of a clear case, with a phone inside"></a><div class="fresh-card-title"><h3>'+e(r['title'])+'</h3><span>$44.99</span></div><a class="fresh-customize" href="'+e(href)+'">Make it yours ↗</a><p class="fresh-credit">Photo: '+e(r['credit'])+' · <a href="ocean-rain-credits.html#'+stem+'">'+e(r['license'])+'</a></p></article>'
 page+='</div></section>'
page+='<footer class="fresh-footer"><h2>Make it your everyday.</h2><p>Choose your phone, add a name if you like, then bring your design to the counter. Personalized and purchased in store.</p><a class="fresh-customize" href="gallery.html">Explore all case designs →</a><p><a href="ocean-rain-credits.html">Photograph sources and licenses</a></p></footer></main><script src="assets/case-zoom.js?v=collection-phone-1"></script></body></html>'
(R/'ocean-and-rain.html').write_text(page+'\n')
credits='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ocean &amp; rain photograph credits | Keepsake</title><style>body{max-width:54rem;margin:auto;padding:2rem 6vw;font:1rem/1.7 system-ui;background:#faf9f6;color:#222}a{color:#853036}section{border-top:1px solid #bbb;padding:1.5rem 0;scroll-margin-top:1rem}h1{line-height:1.1}img{width:150px;height:210px;object-fit:cover;float:right;margin:0 0 1rem 1rem}section:after{content:'';display:block;clear:both}</style></head><body><a href="ocean-and-rain.html">← Ocean &amp; Rain After Dark</a><h1>Photographs &amp; credits</h1><p>These are real photographs. Images are resized and cropped to each phone’s printable area; no scenes are AI-generated. Kelp Light was photographed in the Monterey Bay Aquarium’s kelp forest tank. Digital case previews are composites, not photographs of finished products.</p><p>Source records and licenses are linked below. Cropped or resized versions of ShareAlike photographs are offered under the same license as their source. Attribution accompanies the staff print files.</p>'''
for r in rows:
 stem=Path(r['file']).stem
 credits+='<section id="'+stem+'"><img loading="lazy" src="assets/designs/thumbs/'+r['file']+'" alt="'+e(r['title'])+' photograph"><h2>'+e(r['title'])+'</h2><p><strong>'+e(r['credit'])+'</strong><br>Original title: '+e(r['sourceTitle'])+'</p><p>'+e(r['sourceDescription'])+'</p><p><a href="'+e(r['sourceUrl'])+'">Source photograph and reuse record</a> · '+('<a href="'+e(r['licenseUrl'])+'">'+e(r['license'])+'</a>' if r['licenseUrl'] else e(r['license']))+'</p><p>Adaptation: '+e(r.get('adaptation','Resized and cropped for a phone case.'))+' <a href="assets/designs/'+r['file']+'" download>Download case artwork</a>.</p></section>'
credits+='</body></html>'
(R/'ocean-rain-credits.html').write_text(credits+'\n')
print('Built 12-photo lookbook and credits')
